import { DWClient, DWClientDownStream, TOPIC_ROBOT } from 'dingtalk-stream';

const client = new DWClient({
  clientId: process.env.DINGTALK_APP_KEY!,
  clientSecret: process.env.DINGTALK_APP_SECRET!,
