// 发送工作通知（消息到个人，阅读率最高）
async function sendWorkNotification(params: {
  userIds: string[];
  content: string;
  msgType?: 'text' | 'markdown' | 'action_card';
}) {
  const token = await tokenManager.getAccessToken();

  const body: any = {
