    mydevice@40000000 {
        compatible = "vendor,mydevice";
        reg = <0x40000000 0x1000>;
        interrupts = <GIC_SPI 42 IRQ_TYPE_LEVEL_HIGH>;
        clocks = <&cru CLK_MYDEV>;
        clock-names = "core";
