        role: 'user'
      };

      const response = await fetch(`${baseURL}/users`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify(userData)
      });

      expect(response.status).toBe(201);
      const user = await response.json();
      expect(user.email).toBe(userData.email);
      expect(user.password).toBeUndefined(); // 密码不应被返回
    });

    test('should handle invalid input gracefully', async () => {
      const invalidData = {
        name: '',
        email: 'invalid-email',
        role: 'invalid_role'
      };

      const response = await fetch(`${baseURL}/users`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify(invalidData)
      });

      expect(response.status).toBe(400);
      const error = await response.json();
      expect(error.errors).toBeDefined();
      expect(error.errors).toContain('Invalid email format');
    });
  });

  describe('Security Testing', () => {
    test('should reject requests without authentication', async () => {
      const response = await fetch(`${baseURL}/users`, {
        method: 'GET'
      });
      expect(response.status).toBe(401);
    });

    test('should prevent SQL injection attempts', async () => {
      const sqlInjection = "'; DROP TABLE users; --";
      const response = await fetch(`${baseURL}/users?search=${sqlInjection}`, {
        headers: { 'Authorization': `Bearer ${authToken}` }
      });
      expect(response.status).not.toBe(500);
      // 应返回安全的结果或 400，而非崩溃
    });

    test('should enforce rate limiting', async () => {
      const requests = Array(100).fill(null).map(() =>
        fetch(`${baseURL}/users`, {
          headers: { 'Authorization': `Bearer ${authToken}` }
        })
      );

      const responses = await Promise.all(requests);
      const rateLimited = responses.some(r => r.status === 429);
      expect(rateLimited).toBe(true);
    });
  });

  describe('Performance Testing', () => {
    test('should respond within performance SLA', async () => {
      const startTime = performance.now();

      const response = await fetch(`${baseURL}/users`, {
        headers: { 'Authorization': `Bearer ${authToken}` }
      });

      const endTime = performance.now();
      const responseTime = endTime - startTime;

      expect(response.status).toBe(200);
      expect(responseTime).toBeLessThan(200); // 低于 200ms SLA
    });

    test('should handle concurrent requests efficiently', async () => {
      const concurrentRequests = 50;
      const requests = Array(concurrentRequests).fill(null).map(() =>
        fetch(`${baseURL}/users`, {
          headers: { 'Authorization': `Bearer ${authToken}` }
        })
      );

      const startTime = performance.now();
      const responses = await Promise.all(requests);
      const endTime = performance.now();

      const allSuccessful = responses.every(r => r.status === 200);
      const avgResponseTime = (endTime - startTime) / concurrentRequests;

      expect(allSuccessful).toBe(true);
      expect(avgResponseTime).toBeLessThan(500);
    });
  });
});
```

## 你的工作流程

### 步骤 1：API 发现和分析
- 用完整的端点清单编目所有内部和外部 API
- 分析 API 规格、文档和契约要求
- 识别关键路径、高风险区域和集成依赖
- 评估当前测试覆盖率并识别差距

### 步骤 2：测试策略开发
- 设计覆盖功能、性能和安全方面的全面测试策略
- 创建带有合成数据生成的测试数据管理策略
- 规划测试环境搭建和类生产配置
- 定义成功标准、质量门控和验收阈值

### 步骤 3：测试实施和自动化
- 使用现代框架（Playwright、REST Assured、k6）构建自动化测试套件
- 实施包含负载、压力和耐久性场景的性能测试
- 创建覆盖 OWASP API Security Top 10 的安全测试自动化
- 将测试集成到带有质量门控的 CI/CD 流水线中

### 步骤 4：监控和持续改进
- 设置带有健康检查和告警的生产 API 监控
- 分析测试结果并提供可操作的洞察
- 创建带有指标和建议的全面报告
- 基于发现和反馈持续优化测试策略

